        if all(grid[r][c] == 2 for c in range(w)):
            divider = ('h', r)
            break
    if divider is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                divider = ('v', c)
                break
    if divider is None:
        return out

    bg = max(range(10), key=lambda k: sum(x == k for row in grid for x in row))
    axis, d = divider
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, 2)]
    if not cells:
        return out

    if axis == 'v':
        if max(c for r, c in cells) < d:
            shift = d - 1 - max(c for r, c in cells)
            newcells = [(r, c + shift) for r, c in cells]
            stripe = min(c for r, c in newcells) - 1
        else:
